import { Component, createEffect, createMemo, createSignal, Show } from "solid-js";

import { Icon } from "#core/ui-next/components/icon.jsx";
import { ComponentRegistry } from "#core/ui-next/services/component-registry.js";

import { CommerceCriteriaStatusEntry } from "#base/ui-next/screens/commerce/commerce-screen-model.js";
import { TradeRouteCriteriaTooltip } from "#base/ui-next/tooltips/trade-route-criteria-tooltip.jsx";

import style from "#base/ui-next/components/styles/line-through.scss?url";

export interface CommerceCriteriaDisplayProps {
	status: CommerceCriteriaStatusEntry;
}
const CommerceCriteriaDisplayComponent: Component<CommerceCriteriaDisplayProps> = (props) => {
	const [criteriaMetIcon, setCriteriaMetIcon] = createSignal<string>("");
	const isNegativeOrDoesNotApply = createMemo(() => props.status.isNegative || !props.status.appliesToCurrentCiv);

	createEffect(() => {
		setCriteriaMetIcon(
			isNegativeOrDoesNotApply() ? "url('blp:dip_esp_fail_icon')" : "url('blp:dip_esp_success_icon')",
		);
	});

	const content = (
		<div
			class="w-full flex items-center"
			classList={{ "opacity-50 line-through decoration-secondary": !props.status.appliesToCurrentCiv }}
		>
			<Icon
				class="size-6 mr-2"
				name={criteriaMetIcon()}
				isUrl={true}
			/>
			<div classList={{ "text-negative": props.status.isNegative }}>
				{props.status.statusText ?? "Unset status text"}
			</div>
		</div>
	);

	return (
		<Show
			when={isNegativeOrDoesNotApply()}
			fallback={content}
		>
			<TradeRouteCriteriaTooltip
				text={props.status.tooltipKey}
				header={props.status.statusText}
				isNegative={props.status.isNegative}
				appliesToCurrentCiv={props.status.appliesToCurrentCiv}
			>
				{content}
			</TradeRouteCriteriaTooltip>
		</Show>
	);
};

export const CommerceCriteriaDisplay = ComponentRegistry.register({
	name: "CommerceCriteriaDisplay",
	createInstance: CommerceCriteriaDisplayComponent,
	styles: [style],
	images: ["blp:dip_esp_fail_icon", "blp:dip_esp_success_icon"],
});
